  if (m.includes("gemini")) return "Google Gemini";
  if (m.includes("deepseek-r1") || m.includes("r1")) return "DeepSeek R1";
  if (m.includes("deepseek-v3") || m.includes("v3")) return "DeepSeek V3";
  if (m.includes("deepseek")) return "DeepSeek";
