  if (m.includes("llama-3.3") || m.includes("3.3-70b")) return "Llama 3.3 70B";
  if (m.includes("llama-3")) return "Meta Llama 3";
  if (m.includes("qwen-2.5")) return "Qwen 2.5";
  if (m.includes("qwen")) return "Alibaba Qwen";
  if (m.includes("kimi") || m.includes("moonshot")) return "Moonshot Kimi";
  if (m.includes("sonar")) return "Perplexity Sonar";
  if (m.includes("ollama")) return "Ollama Local";
  if (m.includes("glm-4") || m.includes("zhipu") || m.includes("glm")) return "GLM-4";
  if (m.includes("mimo-v2") || m.includes("mimo") || m.includes("xiaomi")) return "MiMo-V2";
  if (m.includes("nova") || m.includes("titan") || m.includes("bedrock")) return "AWS Bedrock";
  if (m.includes("azure")) return "Azure OpenAI";
  if (m.includes("command-r") || m.includes("cohere")) return "Command R+";
  if (m.includes("together")) return "Together AI";
  if (m.includes("replicate")) return "Replicate";
